import fs from 'node:fs';
import http from 'node:http';
import { chromium } from '/Users/ashahin/code/projects/web/AI-Companion/node_modules/@playwright/test/index.mjs';
const root = '/Users/ashahin/code/projects/web/AI-Companion';
const out = new URL('.', import.meta.url).pathname;
const id = 'ealpmjmaclnlpelpcacmbicmdipmbeei';
const profile = fs.mkdtempSync('/tmp/localpolish-perf-profile-');
const requests = [];
let holdNext=false;
let heldResponse;
let heldClosed=false;
const server = http.createServer(async (req, res) => {
  if (req.method === 'OPTIONS') {
    res.writeHead(204, { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*' });
    res.end();
  } else if (req.method === 'POST') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    requests.push(JSON.parse(raw));
    res.writeHead(200, { 'content-type': 'text/event-stream', 'access-control-allow-origin': '*' });
    if(holdNext){holdNext=false;heldResponse=res;heldClosed=false;res.on('close',()=>{heldClosed=true;});res.write(`data: ${JSON.stringify({choices:[{delta:{content:'Still working'}}]})}\n\n`);return;}
    res.end(`data: ${JSON.stringify({ choices: [{ delta: { content: 'I went home yesterday with my friend.' }, finish_reason: 'stop' }] })}\n\ndata: [DONE]\n\n`);
  } else {
    res.writeHead(200, { 'content-type': 'text/html' });
    if(req.url==='/frames'){res.end('<!doctype html><title>Fake audit frames</title><iframe src="/child"></iframe><iframe src="/child"></iframe><iframe src="/child"></iframe>');return;}
    res.end('<!doctype html><title>Fake draft for performance audit</title><style>textarea{width:600px;height:150px}body{min-height:5000px}</style><textarea id="draft"></textarea>');
  }
});
let context;
const report = { mockOnly: true, baseline: '3638cb0', samples: [] };
try {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  context = await chromium.launchPersistentContext(profile, {
    channel: 'chromium', headless: true,
    args: [`--disable-extensions-except=${root}/dist`, `--load-extension=${root}/dist`],
  });
  let worker;
  for (let i = 0; i < 100; i++) {
    worker = context.serviceWorkers().find(w => w.url().includes(id));
    if (worker) break;
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  if (!worker) throw new Error('No extension worker');
  await worker.evaluate(async base => {
    globalThis.__perfNativeCalls = 0;
    chrome.runtime.connectNative = () => { globalThis.__perfNativeCalls++; throw new Error('Mock-only audit'); };
    await chrome.storage.local.set({ settings: { provider: 'openai-compatible', openaiBaseUrl: base + '/v1', openaiApiKey: 'fake-audit-key', idleFix: true, blocklist: [], models: { 'openai-compatible': 'fake-audit-model' } } });
  }, base);
  for(const initial of context.pages()) await initial.close();
  await new Promise(resolve=>setTimeout(resolve,300));
  await worker.evaluate(()=>{__perfNativeCalls=0;});
  const options = await context.newPage();
  await options.goto(`chrome-extension://${id}/options.html`);
  await options.waitForTimeout(500);
  report.apiOptionsNativeCalls = await worker.evaluate(() => __perfNativeCalls);
  const popup = await context.newPage();
  await popup.goto(`chrome-extension://${id}/popup.html`);
  await popup.waitForTimeout(500);
  report.apiPopupNativeCalls = (await worker.evaluate(() => __perfNativeCalls)) - report.apiOptionsNativeCalls;
  await options.close(); await popup.close();
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  const contexts = [];
  cdp.on('Runtime.executionContextCreated', ({ context }) => contexts.push(context));
  await cdp.send('Runtime.enable');
  await cdp.send('Performance.enable');
  await page.goto(base + '/edit');
  await page.waitForTimeout(500);
  const world = contexts.findLast(c => c.origin === `chrome-extension://${id}`);
  if (!world) throw new Error('No extension isolated world');
  const evaluate = async expression => {
    const r = await cdp.send('Runtime.evaluate', { contextId: world.id, expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
    return r.result.value;
  };
  await evaluate(`(() => {
    globalThis.__perf = { calls: {} };
    for (const [proto, name] of [[Element.prototype,'getBoundingClientRect'],[Document.prototype,'querySelectorAll'],[globalThis,'getComputedStyle']]) {
      const original = proto[name];
      proto[name] = function(...args) { __perf.calls[name] = (__perf.calls[name] || 0) + 1; return Reflect.apply(original,this,args); };
    }
    for (const [proto,name] of [[HTMLElement.prototype,'innerText'],[HTMLTextAreaElement.prototype,'value']]) {
      const d = Object.getOwnPropertyDescriptor(proto,name);
      Object.defineProperty(proto,name,{...d,get(){__perf.calls[name]=(__perf.calls[name]||0)+1;return Reflect.apply(d.get,this,[]);}});
    }
    const schedule=globalThis.setTimeout;
    globalThis.setTimeout=function(fn,delay,...args){if(delay===3000)__perf.calls.idleTimers=(__perf.calls.idleTimers||0)+1;return schedule(fn,delay,...args);};
  })()`);
  const sample = async (name, ms = 3000) => {
    await evaluate('__perf = { calls: {} }');
    const before = Object.fromEntries((await cdp.send('Performance.getMetrics')).metrics.map(m => [m.name,m.value]));
    await page.waitForTimeout(ms);
    const after = Object.fromEntries((await cdp.send('Performance.getMetrics')).metrics.map(m => [m.name,m.value]));
    report.samples.push({ name, durationMs:ms, visible:await page.evaluate(()=>!document.hidden), ...(await evaluate('__perf')), requests:requests.length, rendererMs:Object.fromEntries(['TaskDuration','ScriptDuration','LayoutDuration','RecalcStyleDuration'].map(k=>[k,(after[k]-before[k])*1000])) });
  };
  await sample('no-marker');
  await page.locator('#draft').pressSequentially('i has went home yesterday with my friend');
  await page.locator('.lp-mark').waitFor({ timeout:10000 });
  await sample('visible-marker');
  await page.evaluate(()=>scrollTo(0,2000));
  await sample('offscreen-marker');
  await page.evaluate(()=>scrollTo(0,0));
  const other=await context.newPage(); await other.goto('about:blank'); await other.bringToFront();
  await sample('other-tab-front');
  await other.close(); await page.bringToFront();
  await page.evaluate(()=>document.querySelector('#draft').remove());
  await sample('detached-editor');
  await page.evaluate(()=>{
    const rich=document.createElement('div');rich.id='rich';rich.contentEditable='true';rich.style.cssText='width:600px;min-height:150px;border:1px solid black';document.body.append(rich);scrollTo(0,0);
  });
  await page.locator('#rich').pressSequentially('i has went home yesterday with my friend');
  await page.locator('.lp-mark').waitFor({timeout:10000});
  await sample('rich-marker');
  await worker.evaluate(async()=>{const {settings}=await chrome.storage.local.get('settings');await chrome.storage.local.set({settings:{...settings,idleFix:false}});});
  await page.waitForTimeout(500);
  await page.evaluate(()=>{
    document.querySelector('#rich').remove();const f=document.createElement('textarea');f.id='probe';document.body.append(f);scrollTo(0,0);f.focus();f.value='word '.repeat(2000);f.setSelectionRange(1,5000);
  });
  await page.waitForTimeout(300);
  await evaluate('__perf={calls:{}}');
  report.selectionBurst=await evaluate(`(()=>{const start=performance.now();for(let i=0;i<100;i++)document.dispatchEvent(new Event('selectionchange'));return {events:100,ms:performance.now()-start,calls:{...__perf.calls}};})()`);
  await page.waitForTimeout(250);
  report.selectionAfterDebounce=await evaluate('__perf.calls');
  await page.locator('#probe').fill('');
  await page.waitForTimeout(250);
  await evaluate('__perf={calls:{}}');
  const beforeDisabled=requests.length;
  await page.locator('#probe').pressSequentially('abcdefghij');
  report.disabledTyping={characters:10,calls:await evaluate('__perf.calls')};
  await page.waitForTimeout(3300);
  report.disabledTyping.providerRequests=requests.length-beforeDisabled;
  holdNext=true;
  const testPopup=await context.newPage();await testPopup.goto(`chrome-extension://${id}/popup.html`);
  await testPopup.getByRole('button',{name:'Test connection',exact:true}).click();
  for(let i=0;i<100&&!heldResponse;i++)await page.waitForTimeout(50);
  if(!heldResponse)throw new Error('Held test request did not start');
  report.testConnectionLifecycle={activeBeforeClose:!heldClosed};
  await testPopup.close();await page.waitForTimeout(500);
  report.testConnectionLifecycle.active500msAfterPopupClosed=!heldClosed;
  heldResponse.end('data: [DONE]\n\n');
  await page.waitForTimeout(250);
  const frames=await context.newPage();await frames.goto(base+'/frames');await page.close();await frames.waitForTimeout(500);
  await worker.evaluate(()=>{globalThis.__pageReads=0;chrome.runtime.onMessage.addListener(message=>{if(message?.type==='page-settings')globalThis.__pageReads++;});});
  await worker.evaluate(async()=>{const {settings}=await chrome.storage.local.get('settings');await chrome.storage.local.set({settings:{...settings,models:{...settings.models,'openai-compatible':'fake-audit-model-2'}}});});
  await frames.waitForTimeout(500);
  report.modelOnlySettingsChange={currentFrameCount:frames.frames().length,pageSettingsQueries:await worker.evaluate(()=>__pageReads)};
  report.browser=context.browser()?.version();
  report.result='passed';
} catch(error) { report.result='failed';report.error=error.stack;throw error; }
finally {
  heldResponse?.end();
  await context?.close(); await new Promise(resolve=>server.close(resolve));
  fs.rmSync(profile,{recursive:true,force:true});
  fs.writeFileSync(out+'browser-probe.json',JSON.stringify(report,null,2)+'\n');
  console.log(JSON.stringify(report,null,2));
}

