const root='/Users/ashahin/code/projects/web/AI-Companion';
const out=new URL('.',import.meta.url).pathname;
const report={baseline:'3638cb0',mockOnly:true,node:process.version,diff:[],nativeFrames:[],sse:[]};
for(const words of [300,1200,1500]) {
  const before=Array.from({length:words},(_,i)=>'alpha'+i).join(' ');
  const after=Array.from({length:words},(_,i)=>(words===300?i%20===0:words===1200?i%3===0:true)?'beta'+i:'alpha'+i).join(' ');
  const samples=[];let parts;
  for(let i=0;i<3;i++){const start=performance.now();parts=wordDiff(before,after);samples.push(performance.now()-start);}
  report.diff.push({words,change:words===300?'every20th':words===1200?'every3rd':'all',samplesMs:samples,parts:parts.length});
}
const frame=encodeMessage({type:'rewrite',cli:'claude',user:'x'.repeat(2*1024*1024)});
for(const chunkBytes of [1024,65536]) {
  let copied=0,concats=0,received=0;
  const original=Buffer.concat;
  Buffer.concat=function(list,...args){copied+=list.reduce((s,b)=>s+b.length,0);concats++;return original.call(this,list,...args);};
  const decode=createDecoder(()=>received++);const start=performance.now();
  try{for(let i=0;i<frame.length;i+=chunkBytes)decode(frame.subarray(i,i+chunkBytes));}
  finally{Buffer.concat=original;}
  report.nativeFrames.push({frameBytes:frame.length,chunkBytes,copiedBytes:copied,concats,received,ms:performance.now()-start});
}
for(const chunkBytes of [1024,65536]) {
  const bytes=new TextEncoder().encode('data: '+ 'x'.repeat(2*1024*1024));
  let offset=0,events=0,maxEventChars=0;
  const body=new ReadableStream({pull(c){if(offset>=bytes.length){c.close();return;}c.enqueue(bytes.subarray(offset,offset+chunkBytes));offset+=chunkBytes;}});
  const start=performance.now();
  for await(const event of readSSE(body)){events++;maxEventChars=Math.max(maxEventChars,event.data.length);}
  report.sse.push({inputBytes:bytes.length,chunkBytes,events,maxEventChars,ms:performance.now()-start,note:'Single incomplete data line until EOF. No JSON parser/provider involved.'});
}
const compiled=path.join(out,'compiled-core');fs.mkdirSync(compiled,{recursive:true});fs.writeFileSync(path.join(compiled,'package.json'),'{"type":"commonjs"}');
for(const name of ['background/rewrite','background/providers/cli','core/cleanup','core/messages','core/settings','core/prompts','core/usage']) {
  const source=fs.readFileSync(path.join(root,'src',name+'.ts'),'utf8');
  const result=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}});
  const file=path.join(compiled,name+'.js');fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,result.outputText);
}
const require=createRequire(path.join(compiled,'package.json'));
const {runRewrite}=require(path.join(compiled,'background/rewrite.js'));
const {DEFAULT_SETTINGS}=require(path.join(compiled,'core/settings.js'));
const storage={};globalThis.chrome={storage:{local:{get:async key=>({[key]:storage[key]}),set:async value=>Object.assign(storage,value)}}};
for(const trigger of [undefined,'idle']) {
  const counts={};let finalLength=0;
  await runRewrite({text:'fake draft text only',mode:'fix',tone:'polite',trigger},DEFAULT_SETTINGS,async(_p,_s,onText)=>{for(let i=0;i<1000;i++)onText('x');},event=>{counts[event.type]=(counts[event.type]||0)+1;if(event.type==='done')finalLength=event.text.length;},new AbortController().signal);
  (report.streamMessages??=[]).push({trigger:trigger||'manual',counts,finalLength});
}
const controller=new AbortController();const late=[];
await runRewrite({text:'fake draft text only',mode:'fix',tone:'polite'},DEFAULT_SETTINGS,async(_p,_s,onText)=>{onText('first ');controller.abort();onText('late');},event=>late.push(event.type),controller.signal);
