import fs from 'node:fs';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {performance} from 'node:perf_hooks';
import {encodeMessage,createDecoder} from '/Users/ashahin/code/projects/web/AI-Companion/bridge/lib.mjs';
const root='/Users/ashahin/code/projects/web/AI-Companion';
const out=new URL('.',import.meta.url).pathname;
const bin=fs.mkdtempSync('/tmp/localpolish-fake-versions-');
const log=path.join(bin,'calls.jsonl');
try {
  fs.symlinkSync(process.execPath,path.join(bin,'node'));
  for(const name of ['claude','codex','grok']) {
    const file=path.join(bin,name);
    fs.writeFileSync(file,`#!/usr/bin/env node\nconst fs=require('node:fs');fs.appendFileSync(${JSON.stringify(log)},JSON.stringify({name:${JSON.stringify(name)},args:process.argv.slice(2),at:Date.now()})+'\\n');setTimeout(()=>console.log(${JSON.stringify(name+' fake-version')}),150);\n`,{mode:0o755});
  }
  const start=performance.now();let pong;
  const child=spawn(process.execPath,[root+'/bridge/host.mjs'],{env:{...process.env,PATH:bin},stdio:['pipe','pipe','pipe']});
  child.stdout.on('data',createDecoder(message=>{pong=message;}));let stderr='';child.stderr.on('data',c=>{stderr+=c;});
  child.stdin.write(encodeMessage({type:'ping'}));
  const timer=setTimeout(()=>child.kill('SIGKILL'),5000);
  const exit=await new Promise(resolve=>child.once('close',(code,signal)=>resolve({code,signal})));
  clearTimeout(timer);
  const calls=fs.readFileSync(log,'utf8').trim().split('\n').map(JSON.parse);
  const first=calls[0].at;
  const report={mockOnly:true,fakeVersionDelayMs:150,ms:performance.now()-start,exit,stderr,pong,calls:calls.map(c=>({name:c.name,args:c.args,startAfterFirstMs:c.at-first}))};
  if(calls.length!==3||calls.some(c=>JSON.stringify(c.args)!=='["--version"]')||pong?.type!=='pong'||exit.code!==0)throw new Error('Fake-only ping proof failed');
  fs.writeFileSync(out+'bridge-probe.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
}finally{fs.rmSync(bin,{recursive:true,force:true});}

